// ================= TA DEMANDE : ÉCRIS ICI =================
// Écris ta demande en langage naturel, comme tu me parlerais.
// ===========================================================

const demande = `Un article de blog de 1000 à 1300 mots racontant comment j'ai construit un atelier d'écriture IA entièrement local sur mon Mac, et ce que cette expérience m'a appris.

Les faits à utiliser (n'invente rien d'autre) :
- L'atelier tourne à 100% en local : n8n dans Docker, modèles IA via Ollama, sur un Mac avec 16 Go de RAM
- La chaîne de production : un Interprète transforme ma demande libre en cahier des charges, un Rédacteur écrit, un Critique évalue, un garde-fou en code déterministe (le GATE) valide ou renvoie en réécriture, un Éditeur aligne le style sur un échantillon de ma propre prose
- Une boucle de reprise automatique : si le texte est jugé faible, il est réécrit sans intervention humaine, maximum 2 itérations
- Un Fact-Checker vérifie chaque affirmation factuelle contre un corpus de mes propres briefs validés, indexés dans une base vectorielle locale
- La leçon centrale vécue : un brief vague produit de l'invention plausible, un brief riche en faits produit un texte fidèle - la qualité vient du brief plus que du modèle
- Leçon secondaire : les notes des juges IA mesurent la forme, jamais la vérité - seuls les contrôles en code pur et la relecture humaine garantissent les faits
- Limites honnêtes : qualité de plume inférieure aux grands modèles du marché, 5 à 15 minutes par texte, et une relecture humaine de 5 minutes reste indispensable avant publication

Ton : apprenant curieux qui raconte son cheminement avec ses erreurs, pas expert qui donne des leçons. Première personne. Pas de jargon marketing, pas d'emojis, pas de promesses du type "révolutionnez votre productivité".
Structure : une accroche narrative, le récit du projet, les deux leçons, les limites, et une question ouverte finale aux lecteurs sur ce qu'ils délégueraient - ou pas - à une machine qui écrit.`;

// OPTIONNEL : colle ta prose entre les backticks ci-dessous (sinon laisse tel quel)

const echantillon_style = `(aucun échantillon) COLLE ICI 2 À 3 PAGES DE TA PROPRE PROSE à la place de cette phrase. L'Éditeur imitera ce style. Tant que cette phrase est là, l'Éditeur se contente de fluidifier le texte.`;

// Note : le début du récit apparaissait en double dans l'ancienne version — corrigé.

return [{ json: { demande, echantillon_style } }];

// ===== PARSER LE CAHIER DES CHARGES =====
let brut = ($json.response || "").replace(/<think>[\s\S]*?<\/think>/g, "").trim();
const d = brut.indexOf("{");
const f = brut.lastIndexOf("}");
if (d === -1 || f <= d) {
  throw new Error("L'Interprète n'a pas produit de JSON. Début : " + brut.substring(0, 300));
}
const spec = JSON.parse(brut.substring(d, f + 1));
if (!spec.points_cles || !spec.points_cles.length) {
  throw new Error("Cahier des charges sans points_cles.");
}
spec.longueur_mots_min = spec.longueur_mots_min || 150;
spec.longueur_mots_max = spec.longueur_mots_max || 800;
spec.ton = spec.ton || "clair et direct";
spec.format_notes = spec.format_notes || "prose fluide";

const mem = $getWorkflowStaticData('global');
mem.spec = spec;

return [{ json: { spec, iteration: 1, critiques_eventuelles: "" } }];

// ===== BODY POUR LE RÉDACTEUR (gemma4:e4b) — tout type de texte =====
const mem = $getWorkflowStaticData('global');
const spec = mem.spec;
const iteration = $json.iteration || 1;
const critiques = $json.critiques_eventuelles || "";

const system = `Tu es rédacteur professionnel polyvalent. Tu produis UN texte, en français, conforme à un cahier des charges strict.

RÈGLES ABSOLUES :
1. Ta réponse est UNIQUEMENT le texte demandé. Aucune phrase d'introduction (« Voici le texte »), aucun commentaire, aucune méta-explication. Tu commences directement par le contenu.
2. Tu respectes le TYPE de texte et ses conventions décrites dans format_notes. Un post LinkedIn n'est pas un article : pas de titres markdown si le format ne s'y prête pas.
3. Tu couvres TOUS les points clés du cahier des charges, sans en ajouter d'autres.
4. Tu respectes le ton demandé et la fourchette de longueur en mots. C'est impératif.
5. Chaque affirmation chiffrée ou factuelle précise est marquée [VERIF] juste après.
6. Tu écris uniquement en français : aucun mot ou caractère d'une autre langue.
7. SI des critiques te sont fournies (mode reprise) : tu réécris le texte en corrigeant CHAQUE point critiqué, sans retouches cosmétiques, et tu gardes un marqueur [VERIF] après chaque affirmation factuelle.
8. Tu n'ajoutes AUCUN nom d'outil, de modèle, de marque, de personne ni aucun chiffre qui ne figure pas dans le cahier des charges.`;

const prompt = `CAHIER DES CHARGES :\nType de texte : ${spec.type_texte}\nSujet : ${spec.sujet}\nObjectif : ${spec.objectif}\nTon : ${spec.ton}\nLongueur : entre ${spec.longueur_mots_min} et ${spec.longueur_mots_max} mots\nConventions de format : ${spec.format_notes}\nPoints clés à couvrir :\n${spec.points_cles.map((p, i) => (i + 1) + ". " + p).join("\n")}\n\n${critiques ? "CRITIQUES À CORRIGER (mode reprise) :\n" + critiques + "\n\n" : ""}Rédige le texte.`;

return [{ json: {
  model: "gemma4:e4b",
  system,
  prompt,
  stream: false,
  options: { temperature: 0.8, num_ctx: 16384 },
  _iteration: iteration
} }];

// ===== BODY POUR LE CRITIQUE (qwen2.5:7b, schéma JSON imposé par Ollama) =====
// deepseek-r1 remplacé le 24/09/2026 : il sortait parfois les notes hors de « scores ».
// (Node restauré : il avait été supprimé par accident)
const texte = $json.response;
const mem = $getWorkflowStaticData('global');
const spec = mem.spec;

const system = `Tu es un critique éditorial impitoyable mais juste. Tu évalues UN texte contre son cahier des charges.

RÈGLES ABSOLUES :
1. Tu réponds UNIQUEMENT avec un objet JSON valide conforme au schéma. Aucun texte hors JSON.
2. Tu notes chaque axe de 1 à 10. Un 8+ signifie « publiable tel quel sur cet axe ». Sois sévère : la moyenne attendue d'un premier jet est 6.
3. Pour passages_faibles, tu cites EXACTEMENT 3 extraits textuels (10-30 mots, copiés mot pour mot du texte) avec la raison précise de leur faiblesse. Obligatoire même si le texte est bon.
4. couverture_plan : chaque point clé du cahier des charges avec true/false selon qu'il est réellement traité.
5. respect_format : juge si le texte respecte les conventions du type demandé (un post LinkedIn avec des titres markdown = mauvais score).
6. Tu ne proposes PAS de réécriture. Tu diagnostiques.
7. Tu écris uniquement en français.

SCHÉMA :
{
  \"scores\": {\"clarte\": int, \"tenue_objectif\": int, \"respect_format\": int, \"respect_ton\": int, \"densite_valeur\": int},
  \"couverture_plan\": [{\"point_cle\": string, \"couvert\": boolean}],
  \"passages_faibles\": [{\"extrait\": string, \"probleme\": string}],
  \"verdict_une_phrase\": string
}`;

const prompt = `CAHIER DES CHARGES :\nType : ${spec.type_texte}\nObjectif : ${spec.objectif}\nTon attendu : ${spec.ton}\nFormat attendu : ${spec.format_notes}\nLongueur attendue : ${spec.longueur_mots_min}-${spec.longueur_mots_max} mots\nPoints clés attendus :\n${spec.points_cles.map((p, i) => (i + 1) + ". " + p).join("\n")}\n\nTEXTE À ÉVALUER :\n${texte}\n\nÉvalue.`;

const axe = { type: "integer", minimum: 1, maximum: 10 };
const format = {
  type: "object",
  properties: {
    scores: {
      type: "object",
      properties: { clarte: axe, tenue_objectif: axe, respect_format: axe, respect_ton: axe, densite_valeur: axe },
      required: ["clarte", "tenue_objectif", "respect_format", "respect_ton", "densite_valeur"]
    },
    couverture_plan: { type: "array", items: { type: "object",
      properties: { point_cle: { type: "string" }, couvert: { type: "boolean" } }, required: ["point_cle", "couvert"] } },
    passages_faibles: { type: "array", items: { type: "object",
      properties: { extrait: { type: "string" }, probleme: { type: "string" } }, required: ["extrait", "probleme"] } },
    verdict_une_phrase: { type: "string" }
  },
  required: ["scores", "couverture_plan", "passages_faibles", "verdict_une_phrase"]
};

return [{ json: {
  model: "qwen2.5:7b",
  system,
  prompt,
  stream: false,
  format,
  options: { temperature: 0.2, num_ctx: 16384, num_predict: 1500 },
  _texte: texte
} }];

// ===== GATE DÉTERMINISTE — adapté au cahier des charges =====
let brut = ($json.response || "").replace(/<think>[\s\S]*?<\/think>/g, "").trim();

let evaluation = null;
const d = brut.indexOf("{");
const f = brut.lastIndexOf("}");
if (d !== -1 && f > d) {
  try { evaluation = JSON.parse(brut.substring(d, f + 1)); } catch (e) {}
}

const mem = $getWorkflowStaticData('global');
const spec = mem.spec;
const iteration = $('Préparer requête Rédacteur').first().json._iteration || 1;
const texte = $('Préparer requête Critique').first().json._texte;
const MAX_ITERATIONS = 2;

// Filet de sécurité : si les notes sont au premier niveau au lieu de « scores », on les récupère
const AXES = ["clarte", "tenue_objectif", "respect_format", "respect_ton", "densite_valeur"];
const sansAccent = k => k.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
if (evaluation && (!evaluation.scores || typeof evaluation.scores !== "object")) {
  const aPlat = {};
  for (const [k, v] of Object.entries(evaluation)) if (AXES.includes(sansAccent(k)) && typeof v === "number") aPlat[k] = v;
  if (Object.keys(aPlat).length >= 3) evaluation.scores = aPlat;
}

const schemaOK = evaluation && evaluation.scores && typeof evaluation.scores === "object" && Object.keys(evaluation.scores).length >= 3;

if (!schemaOK) {
  return [{ json: {
    decision: "valide_avec_reserves",
    moyenne: null, iteration,
    alertes: ["Critique illisible : texte validé sans évaluation."],
    verdict: "", reserves: [],
    texte
  } }];
}

const scores = Object.values(evaluation.scores).filter(v => typeof v === "number");
const moyenne = Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 10) / 10;
const minScore = Math.min(...scores);
const planComplet = (evaluation.couverture_plan || []).every(p => p.couvert);

const nbMots = texte.split(/\s+/).length;
const caracteresCJK = /[\u4e00-\u9fff]/.test(texte);
const anneesSuspectes = texte.match(/\b20(1[0-9]|2[0-4])\b/g) || [];
const margeMin = Math.floor(spec.longueur_mots_min * 0.8);
const margeMax = Math.ceil(spec.longueur_mots_max * 1.15);
const alertes = [];
if (nbMots < margeMin || nbMots > margeMax) alertes.push("Longueur hors cible : " + nbMots + " mots (attendu " + spec.longueur_mots_min + "-" + spec.longueur_mots_max + ")");
if (anneesSuspectes.length) alertes.push("Années à vérifier : " + [...new Set(anneesSuspectes)].join(", "));
if (caracteresCJK) alertes.push("Caractères chinois détectés");

const longueurOK = nbMots >= margeMin && nbMots <= margeMax;
const VALIDE = moyenne >= 8 && minScore >= 5 && planComplet && !caracteresCJK && longueurOK;

if (VALIDE || iteration >= MAX_ITERATIONS) {
  return [{ json: {
    decision: VALIDE ? "valide" : "valide_avec_reserves",
    moyenne, min_score: minScore, plan_complet: planComplet,
    iteration, nb_mots: nbMots, alertes,
    verdict: evaluation.verdict_une_phrase || "",
    reserves: VALIDE ? [] : (evaluation.passages_faibles || []),
    texte
  } }];
}

const critiques = [
  "Verdict : " + (evaluation.verdict_une_phrase || ""),
  ...(evaluation.couverture_plan || []).filter(p => !p.couvert).map(p => "Point non traité : " + p.point_cle),
  ...(evaluation.passages_faibles || []).map(p => "Passage faible : « " + p.extrait + " » → " + (p.probleme || p["problème"] || "")),
  ...alertes.map(a => "Contrôle automatique : " + a)
].join("\n");

return [{ json: {
  decision: "reprise",
  moyenne, iteration: iteration + 1,
  critiques_eventuelles: critiques,
  texte
} }];

// ===== FACT-CHECK v2 (24/09/2026) =====
// Sources de vérité : les faits de TA DEMANDE + le corpus des briefs (service port 5077).
// Affirmations vérifiées : celles marquées [VERIF] + celles repérées automatiquement (qwen2.5:7b).
// Verdicts : confirme / contredit (→ réécriture) / absent (→ à vérifier) / opinion (ignoré).
// Garde-fou en code pur : un nom propre ou un chiffre absent des sources => « absent » (à vérifier).
const texte = $json.texte || $json.texte_chapitre || "";
const iteration = $json.iteration || 1;
const OLLAMA = "http://host.docker.internal:11434/api/generate";

if (!texte) {
  return [{ json: {
    ...$json,
    factcheck: { erreur: "Aucun texte reçu — vérifier que FACT-CHECK est branché sur la sortie false de « Reprise ? »" }
  } }];
}

const demande = $('TA DEMANDE (écris ici)').first().json.demande || "";
const norm = s => String(s || "").replace(/\[VERIF\]/g, " ").replace(/[’‘`]/g, "'").replace(/[«»“”]/g, '"')
  .replace(/[*_]/g, "").replace(/\s+/g, " ").trim().toLowerCase();
const texteNorm = norm(texte);

// 1. Affirmations marquées [VERIF] par le Rédacteur
const phrases = texte.split(/(?<=[.!?])\s+/);
const claims = phrases
  .filter(p => p.includes("[VERIF]"))
  .map(p => p.replace(/\s*\[VERIF\]\s*/g, " ").replace(/\s+/g, " ").trim())
  .filter(p => p.length > 15);

// 2. Affirmations repérées automatiquement (le Rédacteur oublie souvent les [VERIF])
let extraction = "ok";
try {
  const ex = await this.helpers.httpRequest({
    method: "POST", url: OLLAMA, json: true, timeout: 300000,
    body: {
      model: "qwen2.5:7b", stream: false,
      system: "Tu repères dans un texte les affirmations FACTUELLES vérifiables : chiffres, durées, quantités, noms d'outils, de modèles ou de technologies, descriptions de fonctionnement, faits historiques. Tu ignores les opinions, émotions, questions et formules de style. Tu COPIES chaque phrase mot pour mot depuis le texte, sans la modifier. Maximum 8.",
      prompt: "TEXTE :\n" + texte,
      format: { type: "object", properties: { affirmations: { type: "array", items: { type: "string" } } }, required: ["affirmations"] },
      options: { temperature: 0, num_ctx: 16384, num_predict: 1200 }
    }
  });
  const trouvees = JSON.parse(ex.response || "{}").affirmations || [];
  for (const c of trouvees) {
    const propre = String(c).replace(/\s*\[VERIF\]\s*/g, " ").replace(/\s+/g, " ").trim();
    // on ne garde que les phrases réellement présentes dans le texte (pas de reformulation)
    if (propre.length > 15 && texteNorm.includes(norm(propre)) && !claims.some(x => norm(x) === norm(propre))) claims.push(propre);
  }
} catch (e) { extraction = "échec : " + e.message; }

if (claims.length === 0) {
  return [{ json: { ...$json, factcheck: { verdicts: [], contredits: 0, absents: 0, note: "aucune affirmation factuelle repérée", extraction } } }];
}

// Garde-fou déterministe : noms propres et chiffres doivent exister dans les sources
const detailsNonSources = (claim, sources) => {
  const s = norm(sources);
  const mots = claim.replace(/\[VERIF\]/g, " ").split(/\s+/);
  const details = new Set();
  mots.forEach((m, i) => {
    const propre = m.replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, "");
    if (!propre) return;
    const debutPhrase = i === 0 || /[.!?:]$/.test(mots[i - 1]);
    if (/\d/.test(propre) || (!debutPhrase && /^\p{Lu}/u.test(propre) && propre.length > 1)) details.add(propre);
  });
  return [...details].filter(d => !s.includes(d.toLowerCase()));
};

// Dédoublonnage : on écarte une affirmation déjà contenue dans une autre
const uniques = claims.filter((c, i) => !claims.some((o, j) => j !== i && norm(o).includes(norm(c)) && (norm(o) !== norm(c) || j < i)));

const verdicts = [];
for (const claim of uniques.slice(0, 12)) {
  let passagesTxt = "(aucun passage trouvé)";
  let serviceOK = true;
  try {
    const retr = await this.helpers.httpRequest({
      method: "POST", url: "http://host.docker.internal:5077/verify",
      body: { claim }, json: true, timeout: 60000
    });
    passagesTxt = (retr.passages || [])
      .map(p => "- (" + p.source + ", dist " + p.distance + ") " + p.texte)
      .join("\n") || "(aucun passage trouvé)";
  } catch (e) {
    serviceOK = false;
    passagesTxt = "(service de corpus injoignable — seuls les faits de la demande sont disponibles)";
  }

  let v = { verdict: "absent", justification: "jugement illisible" };
  try {
    const judge = await this.helpers.httpRequest({
      method: "POST", url: OLLAMA, json: true, timeout: 180000,
      body: {
        model: "qwen2.5:7b", stream: false,
        system: "Tu es vérificateur de faits. Tu compares UNE affirmation aux sources de l'auteur (ses faits fournis + passages de son corpus).\nProcédure : 1) Identifie le fait précis que l'affirmation avance. 2) Cherche dans les sources une phrase qui dit la même chose. 3) Écris ta justification en citant cette phrase, PUIS donne le verdict.\nVerdicts :\n- \"confirme\" : une source dit la même chose, même avec d'autres mots (ex. « 16 Go de mémoire vive » = « 16 Go de RAM » ; « 100% local » = « pas de cloud »).\n- \"contredit\" : une source dit le contraire sur un point précis (autre nombre, négation, autre comparaison).\n- \"absent\" : l'affirmation avance un fait précis (date, durée, chiffre, nom, comparaison) qu'aucune source ne contient.\n- \"opinion\" : ressenti, jugement ou image littéraire, sans fait vérifiable.",
        prompt: "AFFIRMATION :\n" + claim + "\n\nFAITS FOURNIS PAR L'AUTEUR :\n" + demande + "\n\nPASSAGES DU CORPUS :\n" + passagesTxt,
        format: { type: "object", properties: {
          justification: { type: "string" },
          verdict: { type: "string", enum: ["confirme", "contredit", "absent", "opinion"] } }, required: ["justification", "verdict"] },
        options: { temperature: 0, num_ctx: 8192, num_predict: 400 }
      }
    });
    v = JSON.parse(judge.response || "{}");
  } catch (e) {}

  const manquants = detailsNonSources(claim, demande + "\n" + passagesTxt);
  let verdict = v.verdict || "absent";
  let justification = v.justification || "";
  const aDesDetails = detailsNonSources(claim, "").length > 0; // contient au moins un nom propre ou un chiffre
  if (verdict === "contredit" && !aDesDetails) {
    // pas d'élément précis à contredire : on ne relance pas une réécriture pour ça
    verdict = "absent";
    justification = "Contradiction non étayée par un élément précis — à relire. (Le juge IA disait : " + justification + ")";
  }
  if (verdict === "confirme" && manquants.length) {
    verdict = "absent";
    justification = "Détails introuvables dans la demande et les briefs : " + manquants.join(", ") + ". (Le juge IA disait : " + justification + ")";
  }
  verdicts.push({ claim, verdict, justification, ...(serviceOK ? {} : { note: "corpus injoignable" }) });
}

const contredits = verdicts.filter(x => x.verdict === "contredit");
const absents = verdicts.filter(x => x.verdict === "absent");
const opinions = verdicts.filter(x => x.verdict === "opinion");

if (contredits.length > 0 && iteration < 2) {
  const critiques = contredits
    .map(c => "Fait CONTREDIT par tes sources : « " + c.claim + " » → " + c.justification + ". Corrige ou supprime cette affirmation.")
    .join("\n");
  return [{ json: {
    decision: "reprise_factcheck",
    iteration: iteration + 1,
    critiques_eventuelles: critiques,
    texte,
    factcheck: { verdicts, contredits: contredits.length, absents: absents.length }
  } }];
}

return [{ json: {
  ...$json,
  factcheck: {
    verdicts,
    confirmes: verdicts.length - contredits.length - absents.length - opinions.length,
    opinions: opinions.length,
    contredits: contredits.length,
    absents: absents.length,
    a_verifier_manuellement: absents.map(a => a.claim + "  →  " + a.justification),
    extraction
  }
} }];

// ===== BODY POUR L'ÉDITEUR (gemma4:e4b) =====
const texte = $json.texte;
const echantillon = $('TA DEMANDE (écris ici)').first().json.echantillon_style || "";
const avecStyle = echantillon.length > 200 && !echantillon.includes("aucun échantillon");

const reglesStyle = avecStyle
  ? `3. La FORME s'aligne sur l'ÉCHANTILLON DE RÉFÉRENCE fourni : longueur des phrases, rythme, niveau de langue, façon d'ouvrir et fermer les paragraphes.`
  : `3. La FORME vise la fluidité maximale : phrases variées, rythme naturel, aucune lourdeur.`;

const system = `Tu es éditeur littéraire. Tu réécris un texte pour le polir, sans changer le fond.

RÈGLES ABSOLUES :
1. Ta réponse est UNIQUEMENT le texte réécrit. Aucun commentaire.
2. Le FOND est intouchable : mêmes idées, même ordre, mêmes faits, marqueurs [VERIF] conservés à l'identique. Le TYPE et le FORMAT du texte sont conservés (un post reste un post, un email reste un email).
${reglesStyle}
4. Tu élimines : répétitions de mots rapprochées, passives évitables, adverbes creux, phrases de plus de 35 mots.
5. Longueur finale : entre -10% et +5% du texte d'origine.
6. Tu écris uniquement en français.`;

const prompt = (avecStyle ? `ÉCHANTILLON DE RÉFÉRENCE STYLISTIQUE :\n${echantillon}\n\n` : "") + `TEXTE À POLIR :\n${texte}\n\nRéécris.`;

return [{ json: {
  model: "gemma4:e4b",
  system,
  prompt,
  stream: false,
  options: { temperature: 0.5, num_ctx: 16384 }
} }];

// ===== RÉSULTAT FINAL — le texte est ici, et dans le fichier =====
const mem = $getWorkflowStaticData('global');
const spec = mem.spec;
const texteFinal = $json.response;
const infosGate = $('GATE (validation déterministe)').first().json;

let bilanFactcheck = null;
try { bilanFactcheck = $('FACT-CHECK').first().json.factcheck || null; } catch (e) {}

const slug = (spec.sujet || "texte").toLowerCase()
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").substring(0, 40);
const horodatage = new Date().toISOString().slice(0, 16).replace("T", "-").replace(":", "h");
const fileName = "/home/node/sorties/" + (spec.type_texte || "texte").replace(/[^a-zA-Z0-9]+/g, "-") + "-" + slug + "-" + horodatage + ".md";

return [{ json: {
  TEXTE_FINAL: texteFinal,
  factcheck: bilanFactcheck,
  type: spec.type_texte,
  sujet: spec.sujet,
  nb_mots: texteFinal.split(/\s+/).length,
  qualite: { decision: infosGate.decision, moyenne: infosGate.moyenne, iterations: infosGate.iteration, alertes: infosGate.alertes || [] },
  texte: texteFinal,
  fileName
} }];
